import * as THREE from 'three';

function rng(seed=1){let s=seed>>>0;return()=>((s=(s*1664525+1013904223)>>>0)/4294967296)}
function shoreRibbon(width,z,seed=1,opacity=.5){const r=rng(seed),segments=82,v=[],idx=[];for(let i=0;i<=segments;i++){const x=-width/2+width*i/segments;const wave=Math.sin(i*.39+seed)*.085+Math.sin(i*.16+seed*.3)*.05+(r()-.5)*.035;const w=.065+r()*.09;v.push(x,.025,z+wave-w,x,.025,z+wave+w);if(i<segments){const a=i*2,b=a+1,c=a+2,d=a+3;idx.push(a,c,b,b,c,d)}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(v,3));g.setIndex(idx);g.computeVertexNormals();return new THREE.Mesh(g,new THREE.MeshBasicMaterial({color:0xf1ffff,transparent:true,opacity,depthWrite:false,side:THREE.DoubleSide}))}
function sparkleField(width,depth,seed=1,count=320,size=.062,opacity=.82){const r=rng(seed),g=new THREE.BufferGeometry(),positions=[],colors=[];const cs=[new THREE.Color(0xf2ffff),new THREE.Color(0xa9fff4),new THREE.Color(0x65e9e4),new THREE.Color(0xffffff),new THREE.Color(0x7fd6ff)];for(let i=0;i<count;i++){positions.push((r()-.5)*width,.042,(r()-.5)*depth);const c=cs[i%cs.length];colors.push(c.r,c.g,c.b)}g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));return new THREE.Points(g,new THREE.PointsMaterial({size,vertexColors:true,transparent:true,opacity,depthWrite:false,sizeAttenuation:true}))}
function foamRing(radius=.45){const geo=new THREE.RingGeometry(radius*.98,radius*1.24,24,1);const mat=new THREE.MeshBasicMaterial({color:0xf2ffff,transparent:true,opacity:.42,depthWrite:false,side:THREE.DoubleSide});const m=new THREE.Mesh(geo,mat);m.rotation.x=-Math.PI/2;return m}

export function createTargetWaterV3({width=28,depth=6.2,seed=11}={}){
  const g=new THREE.Group();
  const uniforms={uTime:{value:0},uDeep:{value:new THREE.Color(0x07577f)},uMid:{value:new THREE.Color(0x078ca7)},uShallow:{value:new THREE.Color(0x50cfc6)},uLight:{value:new THREE.Color(0xe9ffff)}};
  const mat=new THREE.ShaderMaterial({transparent:true,depthWrite:false,uniforms,
    vertexShader:`varying vec2 vUv;varying float vWave;uniform float uTime;void main(){vUv=uv;vec3 p=position;float w=sin((p.x+uTime*.58)*1.20)*.045+cos((p.y-uTime*.30)*2.05)*.034+sin((p.x*.41+p.y*.77+uTime*.37)*3.2)*.015;p.z+=w;vWave=w;gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.);}`,
    fragmentShader:`varying vec2 vUv;varying float vWave;uniform vec3 uDeep;uniform vec3 uMid;uniform vec3 uShallow;uniform vec3 uLight;uniform float uTime;void main(){float edge=min(vUv.y,1.-vUv.y);float shore=1.-smoothstep(.025,.20,edge);float a=.5+.5*sin(vUv.x*17.3+sin(vUv.y*10.7+uTime*.26)*1.35-uTime*.58);float b=.5+.5*cos(vUv.y*20.1+sin(vUv.x*8.9-uTime*.21)*1.22+uTime*.39);float c1=.5+.5*sin((vUv.x*31.0-vUv.y*13.0)+sin((vUv.x+vUv.y)*11.0)*.7-uTime*.82);float patches=a*b;float glint=pow(max(0.,c1*.72+patches*.42-.56),7.0);float foam=shore*(.35+.65*pow(.5+.5*sin(vUv.x*36.0+sin(vUv.y*19.0)*2.0-uTime*.9),6.0));vec3 c=mix(uDeep,uMid,.48+patches*.16);c=mix(c,uShallow,shore*.50+abs(vWave)*1.75+patches*.10);c=mix(c,uLight,glint*.48+foam*.30);gl_FragColor=vec4(c,.94+shore*.04);}`});
  const mesh=new THREE.Mesh(new THREE.PlaneGeometry(width,depth,88,34),mat);mesh.rotation.x=-Math.PI/2;mesh.receiveShadow=true;g.add(mesh);
  g.add(shoreRibbon(width,depth*.47,seed+1,.52),shoreRibbon(width,-depth*.47,seed+2,.52));
  const area=Math.max(1,width*depth);g.add(sparkleField(width*.95,depth*.87,seed+40,Math.max(240,Math.floor(area*1.8)),.06,.82));
  const rr=rng(seed*7+3),rockMat=new THREE.MeshStandardMaterial({color:0x586461,roughness:.94});
  for(let i=0;i<7;i++){const rad=.18+rr()*.33,x=(rr()-.5)*width*.75,z=(rr()-.5)*depth*.66;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(rad,1),rockMat);rock.position.set(x,.03,z);rock.scale.set(1.15,.62,.92);rock.rotation.y=rr()*Math.PI;rock.castShadow=true;rock.receiveShadow=true;g.add(rock);if(i<5){const ring=foamRing(rad*1.25);ring.position.set(x,.047,z);ring.scale.set(1.2,.86,1);g.add(ring)}}
  g.userData={assetId:'water_target_v3',version:'3.3.0',stage:'M04_PRODUCTION_CANDIDATE',source:'repo-procedural',intent:'bright layered turquoise river with non-linear moving glints, irregular shoreline foam, rock foam rings and dense high-frequency sparkles aligned to TARGET_PS1_FINAL; no grid streaks',update:t=>uniforms.uTime.value=t};
  return g;
}
